{"point":{"id":"agent_access","title":"Agent Canvas Access","rationale":"AgentDiagrammingSessionService binds tool operations to specific canvases or proposals, resolves compact read aliases, enforces access modes, and handles retries. CanvasSessionBridge dispatches commands to browser owners; LiveCanvasService tracks publishers, selection deltas, and reader identities. MCP and HTTP expose this shared application boundary.","sourcePaths":["application/mapping/agent/sessionService.ts","application/mapping/agent/liveCanvasService.ts","application/mapping/agent/apiProjection.ts","application/mapping/agent/ports.ts","domain/mapping/agent/contracts.ts","infrastructure/mapping/agent/canvasSessionBridge.ts","infrastructure/mapping/mcp/server.ts","src/features/mapping/agent/useAgentCanvasBridge.ts","src/server/routes/mapping/liveCanvasRoutes.ts"],"relationships":[{"pointId":"workspace","label":"dispatches commands to the owning browser workspace","kind":"call"},{"pointId":"changes","label":"routes proposal-scoped reads and mutations","kind":"call"},{"pointId":"diagram_generation","label":"starts diagram edits and atomic generation batches","kind":"call"},{"pointId":"contexts","label":"resolves uploaded and saved agent contexts","kind":"call"}]},"sources":[{"path":"application/mapping/agent/sessionService.ts","text":"import { getDiagramRevision } from '../../../domain/core/diagrams/diagramRevisionStore';
import { presentationHighlights } from '../../../domain/core/presentation/diagramPresentation';
