249:             sourceFingerprint: bound.sourceFingerprint, contentHash: materialized.contentHash, snapshot: materialized, ...(resolvedSnapshot ? { resolvedSnapshot } : {}) } : null };
250:       }
251:       if (input.expectedVersion === undefined || !input.expectedRevisionId) throw Error('Expected version and revision are required for context changes');
252:       if (snapshot.version !== input.expectedVersion || diagram.revisionId !== input.expectedRevisionId)
253:         throw Error('VERSION_CONFLICT: read the diagram again');
254:       if (input.operation === 'prepare' && !this.diagramContextStore) throw Error('AGENT_CONTEXT_STORAGE_UNAVAILABLE');
255:       const context = input.operation === 'prepare' ? await storeDiagramAgentContext(compileDiagramAgentContext(diagram), this.diagramContextStore!) : undefined;
256:       if (this.diagramContextMutations.size >= 500) throw Error('Diagram context request capacity reached');
257:       const payload = { operation: input.operation, requestId: input.requestId, expectedVersion: input.expectedVersion,
258:         expectedRevisionId: input.expectedRevisionId, nodeId: input.nodeId, diagramId: diagram.diagramId, ...(context ? { context } : {}) };
259:       this.diagramContextMutations.set(mutationKey, { signature: JSON.stringify(input), canvasId: session.canvasId, documentId: session.documentId, payload });
260:       return this.bridge.dispatch(session.canvasId, { method: 'apply-diagram-context', documentId: session.documentId, payload });
261:     }
262:     if (name === 'exec') return this.exec(agentToolSchemas[name].parse(raw), readOnly);
263:     if (name === 'save_diagram') return this.save(agentToolSchemas[name].parse(raw));
264:     if (name === 'set_diagram_source_mappings') {
265:       const { sessionId, changeSessionId, expectedVersion, requestId, ...fields } = agentToolSchemas[name].parse(raw);
266:       return this.projection.result(await this.apply(sessionId, expectedVersion, [{ method: 'setSourceMappings', ...fields, expectedContentHash: await this.mappingHash(sessionId, changeSessionId, fields.nodeId, expectedVersion) }], requestId, changeSessionId) as EditResult);
267:     }
268:     const input = agentToolSchemas.draw_diagram.parse(raw);
269:     const operation = input.nodeId ? { method: 'replace', nodeId: input.nodeId, ...this.content(input) }
270:       : { method: 'diagram-create', id: `diagram-${randomUUID()}`, parentId: input.parentId, position: input.position, ...this.content(input) };
271:     return this.projection.result(await this.apply(input.sessionId, input.expectedVersion, [operation as DiagramOperation], input.requestId, input.changeSessionId) as EditResult);
272:   }
273:   private async requireRepository(id?: string) {
274:     if (!this.store.repositories) { if (id) throw Error('Repository registry unavailable'); return undefined; }
275:     const repositories = await this.store.repositories.list();
276:     const selected = id ? repositories.find(repo => repo.id === id) : repositories.length === 1 ? repositories[0] : undefined;
277:     if (!selected && (id || repositories.length)) throw Error('Specify a registered repositoryId');
278:     return selected?.id;
279:   }
280:   private changeService() { if (!this.changes) throw new Error('Change sessions unavailable'); return this.changes; }
281:   private content(input: { ascii: string; structureKind?: 'diagram'|'tree'; mappings?: unknown; evidence?: unknown; source?: DiagramSourceBinding }) {
282:     return { ascii: input.ascii, structureKind: input.structureKind, mappings: input.mappings, evidence: input.evidence, source: input.source };
283:   }
284:   private session(id: string, changeSessionId?: string) {
285:     const session = this.sessions.get(id);
286:     if (session && session.changeSessionId !== changeSessionId) throw new Error('CHANGE_SESSION_MISMATCH: attachment and changeSessionId must match');
287:     if (!session || !session.changeSessionId && !this.bridge.list().some(canvas => canvas.canvasId === session.canvasId)) throw new Error('SESSION_UNAVAILABLE: attach to a live canvas');
288:     return session;
289:   }
290:   private binding(sessionId: string, changeSessionId?: string) {
291:     const session = this.session(sessionId, changeSessionId);
292:     return JSON.stringify([session.canvasId, session.documentId, changeSessionId]);
293:   }
294:   private async snapshot(sessionId: string, changeSessionId?: string, options?: { revisionIds?: string[]; currentRevisions?: boolean }): Promise<LiveDocumentSnapshot> {
295:     const session = this.session(sessionId, changeSessionId);
296:     if (session.changeSessionId) return this.changeService().snapshot(session.changeSessionId, session.documentId);
297:     return await this.bridge.dispatch(session.canvasId, { method: 'snapshot', documentId: session.documentId, payload: options }) as LiveDocumentSnapshot;
298:   }
299:   private async attach(canvasId: string, documentId: string, changeSessionId?: string) {
300:     const canvases = changeSessionId ? await this.changeService().descriptor(changeSessionId) : this.bridge.list();
301:     if (!canvases.some(canvas => canvas.canvasId === canvasId && canvas.documents.some(doc => doc.documentId === documentId))) throw new Error('Unknown live document');
302:     return this.attachDocument(canvasId, documentId, changeSessionId);
303:   }
304:   private async attachDocument(canvasId: string, documentId: string, changeSessionId?: string) {
305:     if (this.sessions.size >= 500) throw new Error('Session capacity reached');
306:     const sessionId = randomUUID(); this.sessions.set(sessionId, { canvasId, documentId, changeSessionId });
307:     try {
308:       const snapshot = changeSessionId ? await this.snapshot(sessionId, changeSessionId) : await this.bridge.dispatch(canvasId, { method: 'identity', documentId }) as LiveDocumentSnapshot;
309:       return { sessionId, canvasId, documentId, changeSessionId, repositoryId: snapshot.repositoryId, version: snapshot.version };
310:     } catch (error) { this.sessions.delete(sessionId); throw error; }
311:   }
312:   private async mappingHash(sessionId: string, changeSessionId: string | undefined, nodeId: string, version: number) {
313:     const snapshot = await this.snapshot(sessionId, changeSessionId);
314:     if (snapshot.version !== version) throw Error('VERSION_CONFLICT: read the canvas again');
315:     const box = nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, nodeId.slice(5));
316:     if (!box || box.kind !== 'diagram') throw Error('Expected diagram GridBox');
317:     return snapshot.document.scene.contents[box.contentId].content.asciiSha256;
318:   }
319:   private async apply(sessionId: string, expectedVersion: number, operations: DiagramOperation[], requestId: string, changeSessionId?: string) {
320:     const session = this.session(sessionId, changeSessionId);
321:     if (session.changeSessionId) return this.changeService().apply(session.changeSessionId, session.documentId, expectedVersion, operations, requestId);
322:     return this.bridge.dispatch(session.canvasId, { method: 'apply', documentId: session.documentId, payload: { expectedVersion, operations, requestId, resultNodeIds: operations.flatMap(op => 'nodeId' in op ? [op.nodeId] : op.method === 'diagram-create' ? [`grid:${op.id}`] : []) } });
323:   }
324:   private async applyBatch(sessionId: string, expectedVersion: number, operations: DiagramOperation[], requestId: string, changeSessionId?: string): Promise<CanvasMutationResult> {
325:     const session = this.session(sessionId, changeSessionId);
326:     if (session.changeSessionId) {
327:       const result = await this.changeService().apply(session.changeSessionId, session.documentId, expectedVersion, operations, requestId);
328:       return canvasMutationResult(session.documentId, operations, result);
329:     }
330:     return await this.bridge.dispatch(session.canvasId, { method: 'apply', documentId: session.documentId,
331:       payload: { expectedVersion, operations, requestId, resultFormat: 'receipt' } }) as CanvasMutationResult;
332:   }
333:   private async exec(input: ReturnType<typeof agentToolSchemas.exec.parse>, readOnly = false) {
334:     const key = JSON.stringify([input.changeSessionId, input.sessionId, input.requestId]);
335:     const signature = JSON.stringify(input);
336:     let run = this.execRuns.get(key);
337:     if (run && run.signature !== signature) throw new Error('REQUEST_ID_CONFLICT');
338:     if (!run) {
339:       if (this.execRuns.size >= 2000) throw new Error('Execution retry capacity reached');
340:       const session = input.sessionId && this.session(input.sessionId, input.changeSessionId);
341:       const snapshot = session ? (input.changeSessionId ? await this.snapshot(input.sessionId!, input.changeSessionId)
342:         : await this.bridge.dispatch(session.canvasId, { method: 'identity', documentId: session.documentId }) as LiveDocumentSnapshot) : undefined;
343:       run = { signature, initialVersion: snapshot?.version, version: snapshot?.version, createdDocument: false, steps: [], batches: new Map(),
344:         nodes: snapshot?.document && canvasDisplayNodes(snapshot.document, snapshot.canvas, snapshot.version, snapshot.cell, snapshot.endpointBounds),
345:         edges: snapshot?.document?.edges };
346:       this.execRuns.set(key, run);
347:     }
348:     const state = run;
349:     // A retry replays completed API results and resends only an unacknowledged call.
350:     // The pending call retains its operation ID, expected version and request ID.
351:     const requestPrefix = `exec-${createHash('sha256').update(key).digest('hex')}`;
352:     let cursor = 0;
353:     let pending: number[] = [];
354:     let uncertain = false;
355:     const flush = async () => {
356:       if (uncertain) throw Error('CANVAS_TIMEOUT: retry execution with the same requestId');
357:       if (!pending.length) return;
358:       const indices = pending; pending = [];
359:       const first = indices[0];
360:       let batch = state.batches.get(first);
361:       if (!batch) {
362:         batch = { indices, expectedVersion: state.version! };
363:         state.batches.set(first, batch);
364:       }
365:       if (JSON.stringify(batch.indices) !== JSON.stringify(indices)) throw Error('REQUEST_ID_CONFLICT: batch changed during retry');
366:       if (batch.error) throw batch.error;
367:       if (!batch.result) {
368:         try {
369:           batch.result = await this.applyBatch(input.sessionId!, batch.expectedVersion,
370:             indices.map(index => state.steps[index].operation!), `${requestPrefix}:batch:${first}`, input.changeSessionId);
371:           state.version = batch.result.version; state.nodes = undefined; state.edges = undefined;
372:         } catch (error) {
373:           if (canvasTimeout(error)) uncertain = true;
374:           else batch.error = error;
375:           throw error;
376:         }
377:       }
378:     };
379:     try {
380:       const value = await this.runtime.run(input.code, async (method, args) => {
381:         if (readOnly && !['canvas.read', 'canvas.list', 'canvas.attach', 'nodes.list', 'nodes.get', 'nodes.variants', 'nodes.alternatives', 'edges.list'].includes(method)) throw Error('READ_ONLY: canvas mutation requires Workspace access');
382:         if (input.mode === 'batched' && (method.startsWith('canvas.') || ['nodes.list', 'nodes.get', 'nodes.variants', 'nodes.alternatives', 'edges.list', 'nodes.setSourceMappings', 'nodes.setJumps'].includes(method))) await flush();
383:         if (uncertain) throw Error('CANVAS_TIMEOUT: retry execution with the same requestId');
384:         const stepIndex = cursor++, stepSignature = JSON.stringify({ method, args });
385:         let step = state.steps[stepIndex];
386:         if (step && step.signature !== stepSignature) throw new Error('REQUEST_ID_CONFLICT: execution changed during retry');
387:         if (!step) {
388:           try {
389:             const entry = canvasMethods[method as keyof typeof canvasMethods];
390:             if (!entry) throw new Error('Unknown canvas method');
391:             const resolved = input.sessionId ? this.aliases.resolve(args, this.binding(input.sessionId, input.changeSessionId)) : args;
392:             const parsed = entry.schema.parse(resolved) as Record<string, any>;
393:             let execute: () => Promise<unknown>;
394:             let queuedOperation: DiagramOperation | undefined;
395:             if (method === 'canvas.list') execute = async () => input.changeSessionId ? this.changeService().descriptor(input.changeSessionId) : this.bridge.list();
396:             else if (method === 'canvas.attach') {
397:               if (input.sessionId) {
398:                 const bound = this.session(input.sessionId, input.changeSessionId);
399:                 if (parsed.canvasId !== bound.canvasId || parsed.documentId !== bound.documentId) throw Error('BINDING_MISMATCH: use an unbound execution to attach elsewhere');
400:               }
401:               execute = () => this.attach(parsed.canvasId, parsed.documentId, input.changeSessionId);
402:             }
403:             else if (method === 'canvas.copyDocument') {
404:               if (input.changeSessionId) throw new Error('Copy supports live canvases only');
405:               if (input.sessionId || state.createdDocument) throw new Error('Create one document per unbound exec call');
406:               if (!this.bridge.list().some(canvas => canvas.canvasId === parsed.canvasId && canvas.documents.some(doc => doc.documentId === parsed.documentId)))
407:                 throw new Error('Unknown live document');
408:               state.createdDocument = true;
409:               execute = async () => {
410:                 if (parsed.repositoryId) await this.requireRepository(parsed.repositoryId);
411:                 const result = await this.bridge.dispatch(parsed.canvasId, { method: 'copy-document', documentId: parsed.documentId,
412:                   payload: { name: parsed.name, repositoryId: parsed.repositoryId, expectedVersion: parsed.expectedVersion, requestId: `${requestPrefix}:${stepIndex}` } }) as { documentId: string };
413:                 // The browser has created the document; its descriptor refresh may still be in flight.
414:                 return this.attachDocument(parsed.canvasId, result.documentId);
415:               };
416:             }
417:             else if (method === 'canvas.createDocument') {
418:               if (input.sessionId || state.createdDocument) throw new Error('Create one document per unbound exec call');
419:               state.createdDocument = true;
420:               if (input.changeSessionId && parsed.canvasId !== input.changeSessionId) throw new Error('CHANGE_SESSION_MISMATCH');
421:               execute = async () => {
422:                 if (input.changeSessionId && parsed.repositoryId && (await this.changeService().get(input.changeSessionId)).repositoryId !== parsed.repositoryId)
423:                   throw Error('Proposal canvases inherit the ChangeSession repository');
424:                 const repositoryId = input.changeSessionId ? undefined : await this.requireRepository(parsed.repositoryId);
425:                 const result = input.changeSessionId
426:                   ? await this.changeService().createDocument(input.changeSessionId, parsed.name, input.requestId)
427:                   : await this.bridge.dispatch(parsed.canvasId, { method: 'create-document', payload: { name: parsed.name, repositoryId,
428:                       requestId: input.requestId, snapshot: await this.diagrams.initialize() } }) as { documentId: string };
429:                 return this.attach(parsed.canvasId, result.documentId, input.changeSessionId);
430:               };
431:             } else {
432:               if (!input.sessionId || state.version === undefined) throw new Error('sessionId is required for node operations');
433:               const sessionId = input.sessionId;
434:               if (['nodes.list', 'nodes.get', 'nodes.setJumps'].includes(method) && !state.nodes) {
435:                 const snapshot = await this.snapshot(sessionId, input.changeSessionId);
436:                 if (snapshot.version !== state.version) throw Error('VERSION_CONFLICT: canvas changed during execution');
437:                 state.nodes = canvasDisplayNodes(snapshot.document, snapshot.canvas, snapshot.version, snapshot.cell, snapshot.endpointBounds);
438:                 state.edges = snapshot.document.edges;
439:               }
440:               if (method === 'canvas.read') execute = async () => {

441:                 const session = this.session(sessionId, input.changeSessionId);
442:                 const read = input.changeSessionId ? currentCanvasRead(await this.snapshot(sessionId, input.changeSessionId), parsed as { level: 'small' | 'full'; nodeIds?: string[] })
443:                   : await this.bridge.dispatch(session.canvasId, { method: 'read', documentId: session.documentId, payload: parsed }) as object;
444:                 return this.aliases.project(read, this.binding(sessionId, input.changeSessionId));
445:               };
446:               else if (method === 'edges.list') execute = async () => {
447:                 if (!state.edges) {
448:                   const snapshot = await this.snapshot(sessionId, input.changeSessionId);
449:                   if (snapshot.version !== state.version) throw new Error('VERSION_CONFLICT: canvas changed during execution');
450:                   state.edges = snapshot.document.edges;
451:                 }
452:                 return { version: state.version, edges: state.edges.map(edge => this.projection.edge(edge)) };
453:               };
454:               else if (method === 'nodes.alternatives') execute = async () => {
455:                 const snapshot = await this.snapshot(sessionId, input.changeSessionId);
456:                 if (snapshot.version !== state.version) throw Error('VERSION_CONFLICT: canvas changed during execution');
457:                 const alternatives = snapshot.document.alternatives;
458:                 return { version: state.version, alternatives: Object.values(alternatives?.items ?? {}).filter(item => item.presentationId === parsed.nodeId),
459:                   selected: alternatives?.selected[parsed.nodeId] ?? [], panels: Object.values(alternatives?.panels ?? {}).filter(panel => panel.attachment.diagramPresentationId === parsed.nodeId) };
460:               };
461:               else if (method === 'nodes.variants') execute = async () => {
462:                 const snapshot = await this.snapshot(sessionId, input.changeSessionId);
463:                 if (snapshot.version !== state.version) throw Error('VERSION_CONFLICT: canvas changed during execution');
464:                 const node = canvasDisplayNodes(snapshot.document, snapshot.canvas, snapshot.version).find(node => node.id === parsed.nodeId);
465:                 if (node?.layout !== 'grid' || !node.diagram) throw Error('Expected diagram');
466:                 const variants = Object.values(snapshot.document.revisionReviews ?? {}).filter(variant => variant.contentId === node.diagram!.id);
467:                 const retained = await this.snapshot(sessionId, input.changeSessionId, { revisionIds: variants.flatMap(reviewRevisionIds) });
468:                 if (retained.version !== state.version) throw Error('VERSION_CONFLICT: canvas changed during execution');
469:                 const revisions = retained.history?.diagramRevisions ?? Object.fromEntries((retained.revisions ?? []).map(revision => [revision.id, revision]));
470:                 return { version: state.version, variants: variants.map(variant => ({ variant, ...reviewRevision(variant, id => revisions[id]) })) };
471:               };
472:               else if (method === 'nodes.list') execute = async () => ({ version: state.version, nodes: this.projection.nodes(state.nodes!) });
473:               else if (method === 'nodes.get') execute = async () => {
474:                 const node = state.nodes!.find(node => node.id === parsed.nodeId);
475:                 if (!node) throw new Error('Unknown DisplayNode');
476:                 return this.projection.node(node);
477:               };
478:               else {
479:                 if (input.expectedVersion !== state.initialVersion) throw new Error('VERSION_CONFLICT: mutations require current expectedVersion');
480:                 // Decode before freezing the retry step. Domain state always retains full IDs.
481:                 if (method === 'edges.create' || method === 'edges.update') Object.assign(parsed, this.projection.resolveEdge(parsed as Omit<import('../../../domain/core/diagrams/diagramConnection').DiagramConnection, 'id'>));
482:                 if ((method === 'nodes.collapse' || method === 'nodes.highlight') && parsed.contentNodeId) parsed.contentNodeId = this.projection.resolveAnchorId(parsed.contentNodeId);
483:                 if (method === 'nodes.highlight') {
484:                   parsed.highlightId = `highlight-${randomUUID()}`;
485:                   if (parsed.contentNodeIds) parsed.contentNodeIds = parsed.contentNodeIds.map((id: string) => this.projection.resolveAnchorId(id));
486:                 }
487:                 if (method === 'nodes.setPresentation' && parsed.settings.highlights) {
488:                   parsed.settings.highlights = parsed.settings.highlights.map((item: any) => ({ ...item,
489:                     ...(item.contentNodeId ? { contentNodeId: this.projection.resolveAnchorId(item.contentNodeId) } : {}),
490:                     ...(item.contentNodeIds ? { contentNodeIds: item.contentNodeIds.map((id: string) => this.projection.resolveAnchorId(id)) } : {}) }));
491:                 }
492:                 if (method === 'nodes.setSourceMappings') parsed.expectedContentHash = await this.mappingHash(sessionId, input.changeSessionId, parsed.nodeId, state.version);
493:                 if (method === 'nodes.setJumps') {
494:                   const node = state.nodes!.find(node => node.id === parsed.nodeId);
495:                   if (node?.layout !== 'grid' || !node.diagram) throw Error('Expected diagram GridBox');
496:                   const diagram = node.diagram;
497:                   parsed.jumps = parsed.jumps.map(({ status: _status, ...jump }: any) => {
498:                     const old = diagram.jumps?.find(j => j.id === jump.id && j.source.revisionId === jump.source.revisionId);
499:                     const contentHash = jump.source.contentHash ?? (jump.source.revisionId === diagram.content.revisionId ? diagram.content.asciiSha256 : old?.source.contentHash);
500:                     if (!contentHash) throw Error('STALE_JUMP_SOURCE: read current jump metadata');
501:                     return { ...jump, source: { ...jump.source, contentHash } };
502:                   });
503:                   parsed.jumps = await this.resolveJumps(parsed.jumps, diagram.jumps);
504:                 }
505:                 const expectedVersion = state.version;
506:                 const operation = (method.startsWith('edges.')
507:                   ? method === 'edges.remove' ? { method: 'edge-remove', edgeId: parsed.edgeId }
508:                     : { method: method === 'edges.create' ? 'edge-create' : 'edge-update',
509:                         edge: { ...parsed, id: method === 'edges.create' ? `connection-${randomUUID()}` : parsed.id } }
510:                   : method === 'nodes.promoteAlternative' ? { ...parsed, method: 'alternative-promote' }
511:                   : method === 'nodes.selectAlternative' ? { ...parsed, method: 'alternative-select' }
512:                   : method === 'nodes.removeAlternative' ? { ...parsed, method: 'alternative-remove' }
513:                   : method === 'nodes.sidePanel' ? { ...parsed, method: 'side-panel' }
514:                   : method === 'nodes.selectRevision' ? { ...parsed, method: 'revision-select' }
515:                   : method === 'nodes.reviewVariant' ? { ...parsed, method: 'variant-review' }
516:                   : method === 'nodes.draw' ? { ...parsed, method: 'diagram-create', id: `diagram-${randomUUID()}` }
517:                     : { ...parsed, method: method.slice(6) }) as DiagramOperation;
518:                 if (input.mode === 'batched') {
519:                   queuedOperation = operation;
520:                   // IDs support dependent writes without pretending a queued mutation has committed.
521:                   const handle = 'edge' in operation ? { id: operation.edge.id, edgeId: operation.edge.id }
522:                     : 'edgeId' in operation ? { id: operation.edgeId, edgeId: operation.edgeId }
523:                     : { id: operation.method === 'diagram-create' ? `grid:${operation.id}` : parsed.nodeId,
524:                         nodeId: operation.method === 'diagram-create' ? `grid:${operation.id}` : parsed.nodeId };
525:                   execute = async () => ({ ...handle, status: 'queued' });
526:                 } else execute = async () => {
527:                   const result = await this.apply(sessionId, expectedVersion, [operation], `${requestPrefix}:${stepIndex}`, input.changeSessionId) as EditResult;
528:                   state.version = result.version; state.nodes = undefined; state.edges = undefined; state.lastEdit = result;
529:                   if (method.startsWith('edges.')) return 'edge' in operation ? this.projection.edge(operation.edge) : null;
530:                   const nodeId = operation.method === 'diagram-create' ? `grid:${operation.id}` : parsed.nodeId;
531:                   const node = result.nodes.find(node => node.id === nodeId);
532:                   return node ? this.projection.node(node) : null;
533:                 };
534:               }
535:             }
536:             step = { signature: stepSignature, execute, operation: queuedOperation };
537:             state.steps[stepIndex] = step;
538:           } catch (error) {
539:             state.steps[stepIndex] = { signature: stepSignature, execute: async () => { throw error; }, outcome: { error } };
540:             throw error;
541:           }
542:         }
543:         if (!step.outcome) {
544:           try { step.outcome = { value: await step.execute() }; }
545:           catch (error) { if (!canvasTimeout(error)) step.outcome = { error }; throw error; }
546:         }
547:         if ('error' in step.outcome) throw step.outcome.error;
548:         if (step.operation) pending.push(stepIndex);
549:         return step.outcome.value;
550:       });
551:       await flush();
552:       // A script may catch a transport timeout. Keep it retryable until the unknown
553:       // outcome is acknowledged, rather than reporting a completed execution.
554:       if (state.steps.some(step => !step.outcome)) throw new Error('CANVAS_TIMEOUT: retry execution with the same requestId');
555:       this.execRuns.delete(key);
556:       if (state.batches.size) return { value, transaction: { version: state.version,
557:         receipts: [...state.batches.values()].flatMap(batch => batch.result?.receipts ?? []) } };
558:       return state.lastEdit ? { value, transaction: this.projection.result(state.lastEdit) } : { value, ...(state.version === undefined ? {} : { version: state.version }) };
559:     } catch (error) {
560:       if (uncertain) throw Error('CANVAS_TIMEOUT: retry execution with the same requestId');
561:       if (!canvasTimeout(error)) this.execRuns.delete(key);
562:       throw error;
563:     }
564:   }
565:   private async resolveJumps(input: DiagramJump[], previous: readonly DiagramJump[] = []) {
566:     const resolved = input.map(jump => this.projection.resolveJump(jump));
567:     let catalog: Awaited<ReturnType<DiagramRepository['projectCatalogs']['loadRepresentationCatalog']>> | undefined;
568:     for (let i = 0; i < input.length; i++) {
569:       const handle = input[i].target.contentNodeId;
570:       if (!handle || !this.projection.isAnchorHandle(handle)) continue;
571:       const target = resolved[i].target;
572:       // Existing stale jumps must survive a metadata-only update, just like edges.
573:       if (previous.some(jump => jump.id === input[i].id && jump.target.representationId === target.representationId
574:         && jump.target.displayNodeId === target.displayNodeId && jump.target.contentNodeId === target.contentNodeId)) continue;
575:       if (!catalog) {
576:         const project = await this.store.loadProject();
577:         if (!project) throw Error('STALE_CONTENT_NODE: jump target project is unavailable');
578:         catalog = await (this.store.projectCatalogs.loadCurrentRepresentationCatalog?.(project.id) ?? this.store.projectCatalogs.loadRepresentationCatalog(project.id));
579:       }
580:       const representation = catalog.representations[target.representationId];
581:       const revision = representation && catalog.revisions[representation.currentRevisionId];
582:       const document = revision && documentFromRevision(revision);
583:       const box = document && target.displayNodeId?.startsWith('grid:') && findBox(document.scene.root, target.displayNodeId.slice(5));
584:       if (!box || box.kind !== 'diagram' || !diagramContentNodes(document!.scene.contents[box.contentId].content).some(node => node.id === target.contentNodeId))
585:         throw Error('STALE_CONTENT_NODE: jump handle does not belong to the target diagram revision');
586:     }
587:     return resolved;
588:   }
589:   private async search(input: ReturnType<(typeof agentToolSchemas)['diagram-search']['parse']>) {
590:     if (input.snapshot && (!input.changeSessionId || input.sessionId)) throw Error('snapshot requires changeSessionId without sessionId');
591:     if (input.changeSessionId && !input.sessionId) {
592:       const session = await this.changeService().get(input.changeSessionId);
593:       if (input.revisionId) throw new Error('Session reads use pinned proposal documents, not catalog revisions');
594:       const docs = session.documents.filter(d => !input.representationId || d.id === input.representationId || d.representationId === input.representationId);
595:       if (input.operation === 'read') {
596:         if (docs.length !== 1) throw new Error('Specify representationId (or session document ID) for a session read');
597:         const doc = docs[0], state = doc[input.snapshot ?? 'proposed'];
598:         if (!state) throw Error('New canvas has no baseline');
599:         return { origin: 'change-session', changeSessionId: session.id, documentId: doc.id, name: doc.name, version: doc.version,
600:           snapshot: input.snapshot ?? 'proposed',
601:           nodes: this.projection.nodes(canvasDisplayNodes(state.document, state.canvas, doc.version)),
602:           changeSession: { version: session.version, title: session.title, status: session.status, repositoryId: session.repositoryId, commits: session.commits, head: session.head, diffTree: summarizeChangeSession(session).diffTree, changes: session.changes, migrations: this.projection.migrations(session.migrations) } };
603:       }
604:       const hits = docs.flatMap(doc => {
605:         const state = doc[input.snapshot ?? 'proposed'];
606:         return state ? canvasDisplayNodes(state.document, state.canvas, doc.version).flatMap(node =>
607:         node.layout === 'grid' && node.diagram ? this.matches(node.diagram, input).map(match => ({ origin: 'change-session', documentId: doc.id,
608:           representationId: doc.representationId, name: doc.name, nodeId: node.id, version: doc.version, ...match })) : []) : [];
609:       });
610:       return { total: hits.length, hits: hits.slice(input.offset, input.offset + input.limit),
611:         changeSession: { version: session.version, title: session.title, status: session.status, repositoryId: session.repositoryId, commits: session.commits, head: session.head, diffTree: summarizeChangeSession(session).diffTree, changes: session.changes, migrations: this.projection.migrations(session.migrations) } };
612:     }
613:     if (input.sessionId) {
614:       const snapshot = await this.snapshot(input.sessionId, input.changeSessionId);
615:       const nodes = canvasDisplayNodes(snapshot.document, snapshot.canvas, snapshot.version, snapshot.cell, snapshot.endpointBounds).filter(node => node.layout === 'grid' && node.kind === 'diagram');
616:       if (input.operation === 'read') {
617:         const node = nodes.find(node => node.id === input.nodeId);
618:         if (!node) throw new Error('A valid live nodeId is required');
619:         return { origin: 'live', version: snapshot.version, node: this.projection.node(node), evidence: node.layout === 'grid' ? node.diagram?.sourceContext.evidence ?? {} : {} };
620:       }
621:       const hits = nodes.flatMap(node => node.layout === 'grid' && node.content ? this.matches(node.diagram!, input).map(match => ({ origin: 'live', nodeId: node.id, version: snapshot.version, ...match })) : []);
622:       return { total: hits.length, hits: hits.slice(input.offset, input.offset + input.limit) };
623:     }
624:     const project = await this.store.loadProject();
625:     if (!project) { if (input.operation === 'read') throw new Error('Project is not initialized'); return { total: 0, hits: [] }; }
626:     const catalog = await (this.store.projectCatalogs.loadCurrentRepresentationCatalog?.(project.id, input.revisionId ? [input.revisionId] : undefined) ?? this.store.projectCatalogs.loadRepresentationCatalog(project.id));
627:     const representations = Object.values(catalog.representations).filter(rep => rep.status === 'settled' && (!input.representationId || rep.id === input.representationId));
628:     if (input.operation === 'read') {
629:       const representation = representations.find(rep => rep.id === input.representationId);
630:       if (!representation) throw new Error('A valid representationId is required');
631:       const revisionId = input.revisionId ?? representation.currentRevisionId;
632:       if (!representation.revisionIds.includes(revisionId)) throw new Error('Revision does not belong to representation');
633:       const revision = catalog.revisions[revisionId];
634:       const document = documentFromRevision(revision);
635:       return { origin: 'saved', representation, revision: { id: revision.id, ascii: revision.ascii, revision: revision.revision, createdAt: revision.createdAt, representationKind: revision.representationKind }, nodes: this.projection.nodes(canvasDisplayNodes(document, initialCanvasState(), 0)) };
636:     }
637:     const hits: unknown[] = [];
638:     for (const representation of representations) {
639:       const revision = catalog.revisions[representation.currentRevisionId];
640:       const document = documentFromRevision(revision);
641:       const nodes = canvasDisplayNodes(document, initialCanvasState(), 0);
642:       const query = (input.query ?? '').toLowerCase();
643:       for (const node of nodes) if (node.layout === 'grid' && node.content) {
644:         const matches = this.matches(node.diagram!, input);
645:         if ((!input.mode || input.mode === 'text') && representation.name.toLowerCase().includes(query) && !matches.length) matches.push({ snippet: representation.name });
646:         for (const match of matches) hits.push({ origin: 'saved', representationId: representation.id, revisionId: revision.id, name: representation.name, nodeId: node.id, ...match });
647:       }
648:     }
649:     return { total: hits.length, hits: hits.slice(input.offset, input.offset + input.limit), nextOffset: input.offset + input.limit < hits.length ? input.offset + input.limit : null };
650:   }
651:   private matches(diagram: Diagram, input: ReturnType<(typeof agentToolSchemas)['diagram-search']['parse']>): { snippet: string; contentNodeId?: string; evidenceId?: string; line?: number }[] {
652:     const content = diagram.content, source = diagramSource(diagram);
653:     const q = (input.mode === 'node' && input.query && this.projection.isAnchorHandle(input.query) ? this.projection.resolveAnchorId(input.query) : input.query ?? '').toLowerCase();
654:     if (input.mode === 'code-reference') return source.search(q).map(({mapping,entity}) => ({ snippet: entity.label, evidenceId: mapping.entityId, line: mapping.line }));
655:     if (input.mode === 'node') {
656:       const nodes = content.structure.kind === 'tree' ? Object.values(content.structure.nodes) : [];
657:       return [...nodes.filter(node => `${node.id} ${node.label}`.toLowerCase().includes(q)).map(node => ({ snippet: node.label, contentNodeId: this.projection.anchorId(node.id), line: node.line })),
658:         ...source.entries().filter(({mapping,entity}) => `${mapping.id} ${entity.label}`.toLowerCase().includes(q)).map(({mapping,entity}) => ({ snippet: entity.label, contentNodeId: mapping.id, line: mapping.line }))];
659:     }
660:     return content.ascii.split('\n').flatMap((line, i) => line.toLowerCase().includes(q) ? [{ snippet: line, line: i + 1 }] : []);
661:   }
662:   private save(input: ReturnType<typeof agentToolSchemas.save_diagram.parse>) {
663:     this.session(input.sessionId, input.changeSessionId);
664:     if (input.changeSessionId) throw new Error('CHANGE_SESSION_SAVE_FORBIDDEN: preview edits cannot publish catalog revisions');
665:     const session = this.session(input.sessionId), key = `${session.canvasId}:${session.documentId}`;
666:     const previous = this.saves.get(key) ?? Promise.resolve();
667:     const result = previous.catch(() => undefined).then(() => this.saveNow(input));
668:     this.saves.set(key, result);
669:     void result.finally(() => { if (this.saves.get(key) === result) this.saves.delete(key); }).catch(() => undefined);
670:     return result;
671:   }
672:   private async saveNow(input: ReturnType<typeof agentToolSchemas.save_diagram.parse>) {
673:     const session = this.session(input.sessionId);
674:     if (!input.nodeId) {
675:       const checkpoint = await this.bridge.dispatch(session.canvasId, { method: 'checkpoint', documentId: session.documentId,
676:         payload: { expectedVersion: input.expectedVersion, requestId: input.requestId } }) as { checkpointId: string; representationId?: string; revisionId?: string; repositoryId?: string };
677:       const receipt = await this.diagrams.publishCheckpoint({ documentId: session.documentId, checkpointId: checkpoint.checkpointId,
678:         expectedVersion: input.expectedVersion, requestId: input.requestId, name: input.name, repositoryId: input.repositoryId ?? checkpoint.repositoryId,
679:         representationId: input.representationId ?? checkpoint.representationId, expectedRevisionId: input.expectedRevisionId ?? checkpoint.revisionId });
680:       let displayUpdated = true;
681:       try { await this.bridge.dispatch(session.canvasId, { method: 'saved', documentId: session.documentId, payload: { receipt, requestId: input.requestId, name: input.name } }); }
682:       catch { displayUpdated = false; }
683:       return { representationId: receipt.representation.id, revisionId: receipt.revisionId, savedVersion: receipt.savedVersion, version: receipt.savedVersion, displayUpdated };
684:     }
685:     const snapshot = await this.snapshot(input.sessionId, input.changeSessionId);
686:     if (input.expectedVersion !== snapshot.version) throw new Error('VERSION_CONFLICT: read the canvas again');
687:     let scene = snapshot.document.scene, history = snapshot.history;
688:     if (input.nodeId) {
689:       const node = canvasDisplayNodes(snapshot.document, snapshot.canvas, snapshot.version, snapshot.cell, snapshot.endpointBounds).find(node => node.id === input.nodeId);
690:       if (!node || node.layout !== 'grid' || node.kind !== 'diagram') throw new Error('Expected diagram GridBox');
691:       const box = findBox(scene.root, node.boxId)!;
692:       if (box.kind !== 'diagram') throw new Error('Expected diagram');
693:       const content = scene.contents[box.contentId];
694:       const isolated = singleDiagramScene(content.content.ascii);
695:       scene = { ...isolated, contents: { ...isolated.contents, overview: createStoredDiagram({id:'overview', revision:content.revision, ascii:content.content.ascii, structureKind:content.content.structure.kind, source:content.sourceContext.binding, evidence:content.sourceContext.evidence, mappings:content.sourceContext.mappings}).diagram } };
696:       if (content.jumps) scene = { ...scene, contents: { ...scene.contents, overview: reviseStoredDiagram(scene.contents.overview.revisionId, { kind: 'jumps', jumps: rebaseDiagramJumps(content.content, scene.contents.overview.content, content.jumps) }).diagram } };
697:       const settings = snapshot.document.diagramPresentations?.[box.contentId];
698:       const originalHighlights = presentationHighlights(content, settings, getDiagramRevision(content.revisionId).nodeRefs);
699:       const output = scene.contents.overview, refs = getDiagramRevision(output.revisionId).nodeRefs;
700:       const highlights = rebaseDiagramHighlights(originalHighlights, correspondingNodes(content, output)).map(item => ({ ...item,
701:         nodeRefs: (item.contentNodeIds ?? (item.contentNodeId ? [item.contentNodeId] : [])).map(id => refs[id] ?? `stale:${id}`),
702:         ...(item.textRange && item.revisionId === content.revisionId ? { revisionId: output.revisionId } : {}) }));
703:       const histories = new DefaultCanvasHistoryService();
704:       history = histories.exportContext(histories.openContext({ scene, edges: [], sections: {}, ...(settings || highlights.length ? { diagramPresentations: { overview: { ...settings, highlights } } } : {}) }, snapshot.canvas));
705:     }
706:     const representationId = input.representationId ?? (!input.nodeId ? snapshot.representationId : undefined);
707:     if (!history) throw new Error('Canvas history is required to save');
708:     const save: SaveProjectDiagramInput = { repositoryId: input.repositoryId ?? snapshot.repositoryId, name: input.name, history, scene, edges: input.nodeId ? [] : snapshot.document.edges, representationId,
709:       expectedRevisionId: input.expectedRevisionId ?? (representationId === snapshot.representationId ? snapshot.revisionId : undefined) };
710:     const result = await this.diagrams.save(save);
711:     let displayUpdated = true;
712:     try { await this.bridge.dispatch(session.canvasId, { method: 'saved', documentId: session.documentId, payload: { result, capturedVersion: snapshot.version, wholeDocument: !input.nodeId, savedScene: JSON.stringify(scene), savedEdges: JSON.stringify(input.nodeId ? [] : snapshot.document.edges), name: input.name } }); }
713:     catch { displayUpdated = false; }
714:     return { representationId: result.representation.id, revisionId: result.representation.currentRevisionId, version: snapshot.version, displayUpdated };
715:   }
716: }

